"""Smoke checks for pages generated by scripts/build_site.py; stdlib only."""
import json
import sys
import zipfile
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlparse

ROOT=Path(__file__).resolve().parent.parent
SITE=ROOT/'dist/site'
assert (SITE/'index.html').is_file(), 'First run: python scripts/build_site.py'
html=(SITE/'index.html').read_text(encoding='utf-8')
assert '__SITE_URL__' not in html and '__REPO_URL__' not in html and '__ZIP_NAME__' not in html

class Scanner(HTMLParser):
    def __init__(self): super().__init__(); self.links=[];self.sources=[];self.metatags=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='a' and d.get('href'): self.links.append(d['href'])
        if tag=='img' and d.get('src'): self.sources.append(d['src'])
        if tag=='link' and d.get('href'): self.sources.append(d['href'])
        if tag=='meta': self.metatags.append(d)
s=Scanner();s.feed(html)
assert any('downloads/' in x and x.endswith('.zip') for x in s.links)
for source in [*s.sources,*s.links]:
    if source.startswith(('http:','https:','#','mailto:')):
        continue
    # Page anchor without file is allowed; no root-absolute asset URLs allowed.
    assert not source.startswith('/'), source
    assert (SITE / source.split('#')[0]).exists(), f'Link missing: {source}'
for key in ('og:title','og:description','og:type','og:url','og:image','og:site_name'):
    assert any(tag.get('property')==key and tag.get('content') for tag in s.metatags), key
assert any(tag.get('name')=='twitter:card' for tag in s.metatags)
for filename in ('robots.txt','sitemap.xml','404.html','styles.css','og-image.png','repository-social-preview.png','apple-touch-icon.png','favicon.svg','icon-192.png','icon-512.png'):
    assert (SITE / filename).exists(), filename
assert 'sitemap.xml' in (SITE/'robots.txt').read_text()
assert '<urlset' in (SITE/'sitemap.xml').read_text()
assert '404' in (SITE/'404.html').read_text()
zipfile_path=next((SITE/'downloads').glob('*.zip'))
with zipfile.ZipFile(zipfile_path) as z:
    assert z.testzip() is None
    names=z.namelist()
    assert 'manifest.json' in names and 'popup.js' in names and 'icons/icon128.png' in names
    assert not any(x.startswith(('docs/','tests/')) for x in names)
    manifest=json.loads(z.read('manifest.json'))
    assert manifest['manifest_version']==3 and manifest['version']=='3.0.0'
print('PASS: GitHub Pages HTML metadata, local links, image assets, 404, SEO, installable Chrome ZIP')
